shaders.fragment:
varying vec2 vUv; uniform vec3 uCol, uCore; uniform float uA;
  void main(){ float d = abs(vUv.y - .5) * 2.; float k = 1. - d; float a = pow(k, 1.6) * uA; if (a < .003) discard;
    vec3 c = mix(uCol, uCore, smoothstep(.55, 1., k)); gl_FragColor = vec4(c, a); }

