shaders.fragment:
varying vec2 vUv; uniform float uA, uSeed, uTime, uCut; uniform vec3 uCol;

  float h2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
  float n2(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3.-2.*f);
    return mix(mix(h2(i), h2(i+vec2(1,0)), f.x), mix(h2(i+vec2(0,1)), h2(i+1.), f.x), f.y); }
  float fbm(vec2 p){ return .55*n2(p) + .3*n2(p*2.1+3.7) + .15*n2(p*4.3+7.1); }
  void main(){ float d = length(vUv - .5) * 2.; float n = fbm(vUv * 3.2 + uSeed + vec2(0., -uTime * .35));
    float m = (1. - smoothstep(.25, 1., d + (n - .5) * .7)) * (1. - smoothstep(.8, 1., d)); m -= uCut * (1.1 - n); if (m < .02) discard;
    gl_FragColor = vec4(mix(uCol * .55, uCol, n), m * uA); }
